import { flagEnabled } from "../../lib/flags.js";
import { sparkPath, sparkPoints, weekView } from "../../lib/retention/trend.js";

/**
 * The last seven days, as the account page shows them.
 *
 * The dashboard at `/learn` is generated by the legacy renderer and diffed byte for byte against the
 * static build, so a new panel cannot go there. This is the same data on a page Next owns: points and
 * the streak the database already keeps, plus a sparkline of first-try accuracy read from `attempts`
 * through `retention_week`.
 *
 * A day with no attempts is drawn as a gap rather than as 0%, because a day off is not a wrong answer.
 */

const WEEKDAYS = { weekday: "short", day: "numeric" };

/** `2026-11-05` → `Thu 5`, in the day the database sent rather than the device's zone. */
function dayLabel(day) {
  const at = new Date(`${day}T00:00:00.000Z`);
  if (Number.isNaN(at.getTime())) return day;
  return at.toLocaleDateString("en-GB", { ...WEEKDAYS, timeZone: "UTC" });
}

/** The sparkline's description, one day at a time, for a reader who cannot see the line. */
function describe(week) {
  const studied = week.series.filter((day) => day.accuracy !== null);
  if (studied.length === 0) return "No accuracy to show for the last seven days.";
  const days = studied.map((day) => `${dayLabel(day.day)} ${day.accuracy}%`).join(", ");
  return `First-try accuracy over the last ${week.days} days: ${days}.`;
}

export function WeekPanel({ data, streaks = flagEnabled("streaks") }) {
  const week = weekView(data);
  const points = sparkPoints(week.series);
  const streakDays = week.streak.current === 1 ? "day" : "days";

  return (
    <section className="auth-week" aria-labelledby="this-week">
      <h2 id="this-week">This week</h2>
      <dl className="auth-profile">
        <div>
          <dt>Points today</dt>
          <dd>{week.pointsToday}</dd>
        </div>
        <div>
          <dt>Points in total</dt>
          <dd>{week.pointsTotal}</dd>
        </div>
        {streaks ? (
          <>
            <div>
              <dt>Streak</dt>
              <dd>{`${week.streak.current} ${streakDays}`}</dd>
            </div>
            <div>
              <dt>Longest streak</dt>
              <dd>{week.streak.longest}</dd>
            </div>
          </>
        ) : null}
      </dl>
      {week.empty ? (
        <p className="auth-week-empty">
          Nothing was attempted in the last seven days, so there is no accuracy to show. A finished drill
          fills this in.
        </p>
      ) : (
        <>
          <p className="auth-week-headline">
            {`${week.accuracy}% of ${week.screens} ${week.screens === 1 ? "screen" : "screens"} first try, `}
            {`across ${week.activeDays} of the last ${week.days} days.`}
          </p>
          <svg aria-label={describe(week)} className="auth-spark" role="img" viewBox="0 0 168 40">
            <path d={sparkPath(points)} fill="none" />
            {points.map((point) => (
              <circle cx={point.x} cy={point.y} key={point.day} r="2" />
            ))}
          </svg>
        </>
      )}
    </section>
  );
}
